import java.util.*;import java.time.*;
import com.boothhana.collection.*;import com.boothhana.collection.graph.*;
import static com.boothhana.collection.CollectionModels.*;import static com.boothhana.collection.CatalogModels.*;import static com.boothhana.collection.graph.GraphModels.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;
import tools.jackson.databind.json.JsonMapper;
class ReviewSalesBatch {
 static final JsonMapper json=JsonMapper.builder().build();static JdbcTemplate db;static GraphService graph;
 static String source="https://example.com/review-batch";
 static Map<String,Object> map(Object x){return json.readValue(json.writeValueAsString(x),Map.class);}
 static Map<String,Object> seed(String kind,String target){db.update("update collection_job set available_at=now()+interval '7 days'");var q=graph.seed(new Seed(kind,target,Map.of(),true,UUID.randomUUID().toString()));db.update("update collection_job set available_at=now() where id=?",q.get("id"));return graph.claim();}
 static void approve(Map<String,Object> job,Object result){var audit=new Audit("gpt-6.1-sol","graph-4","graph-4",true,List.of(source),Map.of(),List.of(),List.of(new SourceDocument(source,"a".repeat(64),Instant.now().toString())));var e=map(graph.extract((UUID)job.get("id"),new Extraction((UUID)job.get("leaseToken"),UUID.randomUUID(),job.get("contextHash").toString(),map(result),audit)));graph.decide((UUID)job.get("id"),new Decision((UUID)job.get("leaseToken"),UUID.fromString(e.get("id").toString()),e.get("resultHash").toString(),"APPROVE","Local rollback review fixture",audit));}
 static Map<String,Object> batch(int offset){var sources=List.of(new Source(source,"OFFICIAL","ORIGINAL","Exact named options"));var goods=new ArrayList<ProductData>();for(int i=offset;i<Math.min(103,offset+100);i++)goods.add(new ProductData(null,"Option "+i,"Test option","Maker",List.of(),List.of(),"EVENT_SALE_CONFIRMED",null,"PLANNED",null,sources,List.of(),List.of()));String state=offset==0?"PARTIAL":"COMPLETE";var sales=new Sales("Test sale","EVENT_SALE_CONFIRMED",List.of(),List.of(),"On site",sources,List.of(),goods,List.of());var out=map(new StageResult(state,"Page window",List.of("fixture"),new Coverage(state,103,"PRODUCTS",List.of(source),null,List.of()),List.of(),sales));out.put("pageBatch",Map.of("sourceUrl",source,"sourceHash","a".repeat(64),"offset",offset,"total",103,"labels",goods.stream().map(ProductData::name).toList()));return out;}
 public static void main(String[] args){var ds=new DriverManagerDataSource("jdbc:postgresql://127.0.0.1:55439/boothhana_release_test","boothhana_release_runtime","isolated-interest-test");db=new JdbcTemplate(ds);if(!"boothhana_release_test".equals(db.queryForObject("select current_database()",String.class)))throw new Error("wrong db");var tx=new DataSourceTransactionManager(ds);var status=tx.getTransaction(null);try{
  var media=new CatalogMediaService(db,null,"");var images=new GraphImages(db,json);var identities=new GraphIdentity(db,json);graph=new GraphService(db,json,new GraphProjection(db,json,new CatalogService(db,json,media),new CollectionService(db,json),new CatalogPublicationService(db,json,media),images,identities),images,identities);
  String key=UUID.randomUUID().toString().replace("-","").repeat(2),day=LocalDate.now().plusDays(8).toString();var sources=List.of(new Source(source,"OFFICIAL","ORIGINAL","Test event"));var event=new EventData("Review Event","ONLY_EVENT","Review organizer","2026","SEOUL","Hall","서울특별시 종로구 테스트로 1","Test description","Free",List.of(),List.of(new Occurrence(day,day,"10:00","18:00")),sources,List.of(),List.of(),"MULTI_BOOTH",List.of());
  long eid=db.queryForObject("insert into subculture_event_candidate(identity_key,match_key,name,subcategory,starts_on,ends_on,payload_json,payload_hash,warnings_json) values(?,?,?,'ONLY_EVENT',cast(? as date),cast(? as date),cast(? as jsonb),?,'[]') returning id",Long.class,key,key,event.name(),day,day,json.writeValueAsString(event),key);approve(seed("EVENT",Long.toString(eid)),event);
  var participant=new Participant(null,"Maker","ARTIST",List.of(new Member("Maker","ARTIST",List.of(),source)),List.of(),List.of(),"Description",List.of(source),sources,List.of(),List.of());approve(seed("PARTICIPANTS",Long.toString(eid)),new StageResult("COMPLETE","One participant",List.of("fixture"),new Coverage("COMPLETE",1,"REGISTERED_BOOTHS",List.of(source),null,List.of()),List.of(participant),null));
  long pid=db.queryForObject("select id from subculture_participant where event_id=?",Long.class,eid);approve(seed("SALES",Long.toString(pid)),batch(0));db.update("update collection_job set available_at=now()+interval '7 days'");db.update("update collection_job set available_at=now() where kind='SALES' and target_id=? and state='PENDING' and input_json->'pageBatch'->>'offset'='100'",Long.toString(pid));var next=graph.claim();approve(next,batch(100));
  System.out.println("SALES_BATCH_STATE="+db.queryForObject("select state from collection_job where id=?",String.class,next.get("id")));
  System.out.println("PRODUCT_CHECKS="+db.queryForList("select v->>'state' state,count(*) from subculture_sales,jsonb_each(product_checks_json) c(k,v) where participant_id=? group by v->>'state'",pid));
  System.out.println("PUBLIC_CHECKS="+db.queryForList("select g->'verification'->>'state' state,count(*) from subculture_catalog_publication p,jsonb_array_elements(p.snapshot_json->'participants') person,jsonb_array_elements(person->'productRows') g where p.event_id=? group by g->'verification'->>'state'",eid));
 }finally{tx.rollback(status);System.out.println("ROLLED_BACK=true");}}
}
